INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('ned-stark', 'Eddard "Ned" Stark', 'Stark', 'DEAD', 'Sean Bean', 'Lord of Winterfell, briefly Hand of the King, beheaded by Joffrey.', '#c8ced6');
