INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('robb-stark', 'Robb Stark', 'Stark', 'DEAD', 'Richard Madden', 'King in the North, killed at the Red Wedding.', '#c8ced6');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('sansa-stark', 'Sansa Stark', 'Stark', 'ALIVE', 'Sophie Turner', 'Eldest Stark daughter, becomes Queen in the North.', '#c8ced6');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('arya-stark', 'Arya Stark', 'Stark', 'ALIVE', 'Maisie Williams', 'Younger Stark daughter, trained as a Faceless Man, kills the Night King.', '#c8ced6');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('bran-stark', 'Bran Stark', 'Stark', 'ALIVE', 'Isaac Hempstead Wright', 'Becomes the Three-Eyed Raven, later King of the Six Kingdoms.', '#c8ced6');
