INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('rodrik-cassel', 'Rodrik Cassel', 'Stark', 'DEAD', 'Ron Donachie', 'Master-at-arms of Winterfell, executed by Theon Greyjoy.', '#c8ced6');
