INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('hodor', 'Hodor (Wylis)', 'Stark', 'DEAD', 'Kristian Nairn', 'Gentle Winterfell stableboy who gives his life holding a door for Bran and Meera.', '#c8ced6');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('osha', 'Osha', 'Stark', 'DEAD', 'Natalia Tena', 'Wildling captured at Winterfell who becomes Bran and Rickon''s protector; killed by Ramsay.', '#c8ced6');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('jojen-reed', 'Jojen Reed', 'Stark', 'DEAD', 'Thomas Brodie-Sangster', 'Greenseer who guides Bran north; dies protecting him from wights.', '#c8ced6');
