INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('howland-reed', 'Howland Reed', 'Stark', 'ALIVE', 'actor unknown', 'Lord of Greywater Watch, present at the Tower of Joy with Ned Stark.', '#c8ced6');
