INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('lord-cerwyn', 'Lord Cerwyn', 'Stark', 'ALIVE', 'actor unknown', 'Minor Northern lord who attends Sansa''s councils at Winterfell.', '#c8ced6');
