INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('axell-florent', 'Axell Florent', 'Baratheon', 'DEAD', 'actor unknown', 'Selyse''s uncle and an advisor at Dragonstone.', '#d4af37');
INSERT INTO character_records (id, name, house, status, actor, biography, sigil_color) VALUES ('maester-cressen', 'Maester Cressen', 'Baratheon', 'DEAD', 'Oliver Ford Davies', 'Stannis''s old maester, poisons himself trying to kill Melisandre and fails.', '#d4af37');
